// Extract, deduplicate, and detect vendor for each URL
const raw = $input.first().json['Product Links'] || '';
const addedBy = $input.first().json['Added By'] || 'Zuha';

// Map Added By to ClickUp option UUID
const addedByMap = {
  'Zuha': 'bac4e09e-7cf7-4f0f-b0f9-bac89528a23a',
  'Fiancé': 'f366c6e5-9a52-47c1-a5ea-fc421f30bc82'
};
const addedByUuid = addedByMap[addedBy] || addedByMap['Zuha'];

// Extract all URLs from the textarea
const urlRegex = /https?:\/\/[^\s,\"<>]+/g;
const matches = raw.match(urlRegex) || [];

// Deduplicate
const unique = [...new Set(matches.map(u => u.trim()))];

if (unique.length === 0) {
  throw new Error('No valid URLs found in submission. Please paste at least 1 product URL.');
}
if (unique.length > 20) {
  throw new Error(`Too many URLs: ${unique.length} submitted, maximum is 20.`);
}

// Vendor detection
function detectVendor(url) {
  const u = url.toLowerCase();
  if (u.includes('amazon.') || u.includes('a.co/') || u.includes('amzn.to/')) return { name: 'Amazon', uuid: '6473fbf4-63fa-4fb0-9837-84063f9446b7' };
  if (u.includes('crateandbarrel') || u.includes('cb2.')) return { name: 'Crate & Barrel', uuid: '13dab330-bb97-4adf-b98c-ee7b555e53c1' };
  if (u.includes('williams-sonoma') || u.includes('williams sonoma') || u.includes('wsimgs')) return { name: 'Williams Sonoma', uuid: '736e36a7-799a-40ce-bf19-976838b9f18b' };
  if (u.includes('target.com')) return { name: 'Target', uuid: 'b27937ac-992b-4eea-bccd-df367fa228d2' };
  if (u.includes('bestbuy.com')) return { name: 'Best Buy', uuid: '902471bb-b070-4200-aefd-1662819c7425' };
  return { name: 'Direct / Universal', uuid: '26e06bbb-3c70-4232-b4d9-ae80f976443b' };
}

// Extract URL slug as fallback product name
function slugToName(url) {
  try {
    const u = new URL(url);
    const parts = u.pathname.split('/').filter(p => p.length > 3 && !/^\d+$/.test(p));
    if (parts.length > 0) {
      return parts[parts.length - 1]
        .replace(/[-_]/g, ' ')
        .replace(/\b\w/g, c => c.toUpperCase())
        .substring(0, 100);
    }
  } catch (e) {}
  return null;
}

const items = unique.map((url, i) => {
  const vendor = detectVendor(url);
  const slugName = slugToName(url);
  return {
    url,
    index: i,
    vendor,
    slugName,
    addedBy,
    addedByUuid,
    taskName: slugName || `Registry Item ${i + 1}`
  };
});

return items.map(item => ({ json: item }));

// Parse OG tags from scraped HTML; fall back to URL slug
const item = $input.item.json;
const html = $input.item.json.data || '';

function extractOg(html, prop) {
  const re = new RegExp(`<meta[^>]*property=['"]og:${prop}['"][^>]*content=['"]([^'"]+)['"]`, 'i');
  const re2 = new RegExp(`<meta[^>]*content=['"]([^'"]+)['"][^>]*property=['"]og:${prop}['"]`, 'i');
  const m = html.match(re) || html.match(re2);
  return m ? m[1].trim() : null;
}

const isCaptcha = /robot check|captcha|are you human|verify you are/i.test(html);
const is403 = item.statusCode === 403 || item.error;

let productName = null;
let price = null;
let scrapeSucceeded = false;

if (!isCaptcha && !is403 && html.length > 100) {
  productName = extractOg(html, 'title');
  price = extractOg(html, 'price:amount') || extractOg(html, 'price');
  scrapeSucceeded = !!productName;
}

// Fall back to slug name
if (!productName) {
  productName = item.slugName || item.taskName;
}

// Parse price to number
let retailPrice = null;
if (price) {
  const num = parseFloat(price.replace(/[^0-9.]/g, ''));
  if (!isNaN(num)) retailPrice = num;
}

// Determine price bracket UUID
let priceBracketUuid = null;
if (retailPrice !== null) {
  if (retailPrice < 50) priceBracketUuid = '1949e004-587e-4b77-8c4c-87e49d4aef46';
  else if (retailPrice <= 150) priceBracketUuid = 'e8087ca4-e624-4baf-a022-62240f5f7b59';
  else if (retailPrice <= 300) priceBracketUuid = '54048e14-106c-4211-a287-f935f924a246';
  else priceBracketUuid = '0803e69d-5b32-4323-917b-377bddf2ea4a';
}

return [{
  json: {
    ...item,
    productName,
    retailPrice,
    priceBracketUuid,
    scrapeSucceeded,
    blocked: isCaptcha || is403
  }
}];

// Aggregate all items into succeeded/blocked buckets
const allItems = $input.all();

const succeeded = allItems.filter(i => !i.json.blocked && !i.json.error);
const blocked = allItems.filter(i => i.json.blocked);

return [{
  json: {
    totalCount: allItems.length,
    succeededCount: succeeded.length,
    blockedCount: blocked.length,
    succeededItems: succeeded.map(i => i.json.productName || i.json.url),
    blockedItems: blocked.map((i, idx) => `${idx + 1}. ${i.json.url}`)
  }
}];

// Build digest comment for the ClickUp list
const items = $input.first().json;
const lines = (items.succeededItems || []).map((name, i) => `${i + 1}. ${name}`);
const msg = `Registry Intake Digest\n\nAdded ${items.succeededCount} item(s):\n${lines.join('\n')}`;
return [{ json: { message: msg, listId: '1300320000015716' } }];
